def count_char(text, target):
    if len(text) == 0:
        return 0
    first = 1 if text[0] == target else 0
    return first + count_char(text[1:], target)

print(count_char("satellite", "l"))

def flatten(lst):
    result = []
    for item in lst:
        if type(item) == list:
            result = result + flatten(item)
        else:
            result.append(item)
    return result

print(flatten([1, [2, [3]], 4]))

def binary_search(numbers, target):
    left = 0
    right = len(numbers) - 1
    while left <= right:
        mid = (left + right) // 2
        if numbers[mid] == target:
            return mid
        elif numbers[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

print(binary_search([2, 5, 8, 12], 6))

def find_value(sorted_list, target):
    if len(sorted_list) == 0:
        return False
    mid = len(sorted_list) // 2
    if sorted_list[mid] == target:
        return True
    elif sorted_list[mid] < target:
        return find_value(sorted_list[mid + 1:], target)
    else:
        return find_value(sorted_list[:mid], target)

print(find_value([9, 2, 7, 4, 1], 9))

